CREATE TABLE client_organizations(id BINARY(16) PRIMARY KEY,tenant_id BINARY(16) NOT NULL,slug VARCHAR(255) NOT NULL UNIQUE,name VARCHAR(255) NOT NULL,INDEX idx_client_org_tenant(tenant_id));
CREATE TABLE client_applications(id BINARY(16) PRIMARY KEY,organization_id BINARY(16) NOT NULL,name VARCHAR(255) NOT NULL,client_key VARCHAR(255) NOT NULL UNIQUE,integration_status VARCHAR(255) NOT NULL,FOREIGN KEY(organization_id) REFERENCES client_organizations(id) ON DELETE CASCADE);
CREATE TABLE client_environments(id BINARY(16) PRIMARY KEY,application_id BINARY(16) NOT NULL,name VARCHAR(255) NOT NULL,state VARCHAR(255) NOT NULL,FOREIGN KEY(application_id) REFERENCES client_applications(id) ON DELETE CASCADE);
CREATE TABLE client_allowlist(id BINARY(16) PRIMARY KEY,environment_id BINARY(16) NOT NULL,type VARCHAR(20) NOT NULL,value VARCHAR(255) NOT NULL,FOREIGN KEY(environment_id) REFERENCES client_environments(id) ON DELETE CASCADE);
CREATE TABLE client_entitlements(id BINARY(16) PRIMARY KEY,application_id BINARY(16) NOT NULL,game_id BINARY(16) NOT NULL,territory VARCHAR(255) NOT NULL,expires_at TIMESTAMP(6),FOREIGN KEY(application_id) REFERENCES client_applications(id) ON DELETE CASCADE,INDEX idx_entitlement_game(game_id));
